package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="injury_records", indexes={@Index(name="idx_injury_player", columnList="player_id"),@Index(name="idx_injury_recovered", columnList="recovered")})
public class InjuryRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; private String injuryType; private String severity; private LocalDate startDate; private LocalDate endDate; private Boolean recovered=false; @Column(length=1000) private String notes; public boolean isActiveInjury(){return !Boolean.TRUE.equals(recovered)&&(endDate==null||!endDate.isBefore(LocalDate.now()));} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public String getInjuryType(){return injuryType;} public void setInjuryType(String injuryType){this.injuryType=injuryType;} public String getSeverity(){return severity;} public void setSeverity(String severity){this.severity=severity;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate startDate){this.startDate=startDate;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate endDate){this.endDate=endDate;} public Boolean getRecovered(){return recovered;} public void setRecovered(Boolean recovered){this.recovered=recovered;} public String getNotes(){return notes;} public void setNotes(String notes){this.notes=notes;} }
